extraCss:
.slide--title h1,.slide--section h2{font-family:var(--f-display);font-weight:400;letter-spacing:0}
.card{background:color-mix(in srgb, var(--paper) 84%, white)}
.slide--section{background:var(--accent)}
.slide--section h2,.slide--section .num{color:var(--paper)}
.slide--section .kick,.slide--section .note{color:color-mix(in srgb, var(--paper) 70%, transparent)}
